<?php
namespace App\Http\Controllers;use App\Models\{Product,Category};use Illuminate\Http\Request;class ProductController extends Controller{public function index(Request $r){$q=Product::with('category')->where('is_active',true);if($r->filled('q'))$q->where(fn($x)=>$x->where('name','like','%'.$r->q.'%')->orWhere('description','like','%'.$r->q.'%'));if($r->filled('category'))$q->where('category_id',$r->integer('category'));$col='price_'.(session('currency','USD')==='CDF'?'cdf':'usd');if($r->filled('min'))$q->where($col,'>=',$r->input('min'));if($r->filled('max'))$q->where($col,'<=',$r->input('max'));if($r->input('sort')==='price_asc')$q->orderBy($col);elseif($r->input('sort')==='price_desc')$q->orderByDesc($col);else $q->latest();return view('products.index',['products'=>$q->paginate(12)->withQueryString(),'categories'=>Category::where('is_active',true)->get(),'currency'=>session('currency','USD')]);}public function category(Category $category){return view('products.index',['products'=>$category->products()->with('category')->where('is_active',true)->paginate(12),'categories'=>Category::where('is_active',true)->get(),'currency'=>session('currency','USD')]);}public function show(Product $product){abort_unless($product->is_active,404);$product->load(['category','reviews.user']);return view('products.show',['product'=>$product,'currency'=>session('currency','USD')]);}}
